from __future__ import annotations
import json

def build_semantic_orchestrator_messages(message:str,case_state:dict,recent_turns:list[dict]|None=None)->list[dict]:
    schema={"route":"one allowed route","intent":"one allowed intent","confidence":0.0,"next_action":"respond_deterministically|update_case|ask_clarification|retrieve|escalate|legacy_fallback","requires_retrieval":False,"requires_clarification":False,"requires_escalation":False,"topic_shift":False,"case_updates":[{"type":"product|process|symptom|attempted_action|attempt_result|affected_scope|error_message|evidence|technical_context|resolution_status","value":"fact explicitly supported by the current message","confidence":0.0}],"missing_information":[],"clarification_question":None,"retrieval_request":None,"reasoning_summary":"brief explanation without hidden chain of thought"}
    system="""You are the semantic orchestrator for Arus PrintAssist, an enterprise print-support assistant. Understand meaning, paraphrases, misspellings, indirect references, and conversation context. Do not depend on exact keywords. Return ONLY one valid JSON object, no markdown. Never invent a product, symptom, action, result, impact, evidence, or error. case_updates must contain only facts supported by the CURRENT user message. Use the case state only to resolve references. Decide whether retrieval is needed. Case details normally update state without retrieval. Requests for a next technical step require retrieval only when a concrete product/domain and problem statement are available. Technical procedures and factual claims require retrieval. Greetings, acknowledgements, intake, clarification, and pure case updates do not. If technical context is insufficient, ask one focused clarification. Internal model knowledge may interpret language but is not evidence for technical procedures. Never expose chain of thought; reasoning_summary must be short and operational."""
    user={"current_message":message,"case_state":case_state,"recent_turns":recent_turns or [],"allowed_routes":["social","capabilities","support_intake","case_update","clarification","technical_query","technical_follow_up","explicit_source","escalation","out_of_scope"],"allowed_intents":["social","conceptual","procedural","troubleshooting","requirements","warranty","architecture","escalation","unknown"],"output_schema":schema}
    return [{"role":"system","content":system},{"role":"user","content":json.dumps(user,ensure_ascii=False)}]
